"""Invoice records."""


class Invoice:
    def __init__(self, client, due):
        self.client = client
        self.due = due

    def __repr__(self):
        return "Invoice(%r, %r)" % (self.client, self.due)


ROWS = [('juno', 32), ('kite', 5), ('hale', 34), ('juno', 19), ('juno', 46), ('ivory', 59), ('ivory', 23)]


def load_invoices():
    """Yield the stored invoices one at a time."""
    for client, due in ROWS:
        yield Invoice(client, due)

