"""A book of invoices with a cached total."""


class InvoiceBook:
    def __init__(self):
        self._invoices = []
        self._total = None

    def add(self, invoice):
        """Add one invoice to the book."""
        self._invoices.append(invoice)

    def total(self):
        """Return the total due of the invoices in the book."""
        if self._total is None:
            self._total = sum(x.due for x in self._invoices)
        return self._total

    def count(self):
        """Return how many invoices the book holds."""
        return len(self._invoices)

